contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, bool freeze) public {
        uint256 tsBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 targetBalBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;
        assert(c.totalSupply() == tsBefore
            && c.balanceOf(address(this)) == ownerBalBefore
            && c.balanceOf(target) == targetBalBefore);
    }
    receive() external payable {}
}

